 "content": "from collections import Counter, deque


def transform(grid):
    """Swap the outermost and innermost colors in each nonzero nested object."""
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))

            # Distance inward from the object's exterior boundary.
            dist = {}
            q = deque()
            for y, x in comp:
                if any(not (0 <= y + dy < h and 0 <= x + dx < w) or g[y + dy][x + dx] == 0
                       for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                    dist[(y, x)] = 0
                    q.append((y, x))
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if p in seen and p not in dist and g[p[0]][p[1]] != 0:
                        dist[p] = dist[(y, x)] + 1
                        q.append(p)
            outer = Counter(g[y][x] for y, x in comp if dist[(y, x)] == 0).most_common(1)[0][0]
            max_depth = max(dist.values())
            inner = Counter(g[y][x] for y, x in comp if dist[(y, x)] == max_depth).most_common(1)[0][0]
            if outer != inner:
                for y, x in comp:
                    if g[y][x] == outer:
                        g[y][x] = inner
                    elif g[y][x] == inner:
                        g[y][x] = outer
    return g
