                    if 0 <= ny < h and 0 <= nx < w and g[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))

            # Distance from the exterior gives each nested rectangular color band
            # an inward depth. Reverse the order of the band colors.
            dist = {}
            q = deque()
            for y, x in comp:
                if any(not (0 <= y + dy < h and 0 <= x + dx < w) or g[y + dy][x + dx] == 0
                       for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                    dist[(y, x)] = 0
                    q.append((y, x))
            comp_set = set(comp)
            while q:
                y, x = q.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if p in comp_set and p not in dist:
                        dist[p] = dist[(y, x)] + 1
                        q.append(p)

            first_depth = {}
            for p in comp:
                color = g[p[0]][p[1]]
                first_depth[color] = min(first_depth.get(color, 10**9), dist[p])
